RESULT_LINKS={}
if (REAL_EXAMPLE_ROOT/'provenance.json').is_file():
    GUIDES[REAL_EXAMPLE_TOPIC]='''<p>These images come from a completed production S4 · RCWA calculation of the bundled example: a 220 nm Silicon layer on semi-infinite SiO₂, with centered circular Air holes of 100 nm radius and a 540 nm square lattice. Air is the incident medium.</p><p>The spectrum has 41 calculated samples from 1515 to 1555 nm at 1 nm spacing, p polarization and normal incidence. The recorded run requested Fourier basis 81 and used CPU calculation. Silicon n=3.48, SiO₂ n=1.45 and Air n=1; k=0 for all three. These constant indices are explicit demonstration approximations.</p><p>The field maps are calculated at 1550 nm with 25 samples per axis and 3 volume depths in the Silicon layer. Linear |E| is normalized to incident electric-field amplitude. XY is the mid-layer plane at z=0.11 µm; XZ is y=0 through the 0.22 µm film. Plot coordinates are µm; spectrum wavelength is nm. Spectrum graphs use 0–100% of incident power; raw CSV R/T/A remain power fractions.</p><p>The bundled validation records finite R/T/A and complex fields, lossless R+T balance, and requested basis 49/81/121 spectrum comparison. This smooth example spectrum does not establish a resonance. Spectral basis checks do not establish spatial field convergence or experimental material accuracy.</p><p><a href="guide:help_assets/silicon-reference-run/results.csv">Open actual spectrum CSV</a> · <a href="guide:help_assets/silicon-reference-run/electric_fields.csv">Open actual complex field CSV</a> · <a href="guide:help_assets/silicon-reference-run/project.json">Open calculation inputs</a> · <a href="guide:help_assets/silicon-reference-run/scientific-validation.json">Open scientific validation</a> · <a href="guide:help_assets/silicon-reference-run/bundle.json">Open portable provenance and file checksums</a></p><p><a href="guide:help_assets/silicon-reference-run/actual-spectrum-native.png">Open full native spectrum workspace</a> · <a href="guide:help_assets/silicon-reference-run/actual-fields-native.png">Open full native Fields workspace</a></p>'''
    GUIDES[REAL_EXAMPLE_TOPIC]+='''<p><a href="guide:help_assets/silicon-reference-run/field-samples.json">Open the portable index of all 41 wavelength field datasets</a> · <a href="guide:help_assets/silicon-reference-run/basis-49/results.csv">Open basis 49 comparison CSV</a> · <a href="guide:help_assets/silicon-reference-run/basis-121/results.csv">Open basis 121 comparison CSV</a></p><p><a href="guide:help_assets/silicon-reference-run/actual-spectrum-export.png">Open high-resolution spectrum export</a> · <a href="guide:help_assets/silicon-reference-run/actual-electric-field-maps.png">Open high-resolution field-map export</a></p>'''
    TOPIC_IMAGES[REAL_EXAMPLE_TOPIC]=('silicon-reference-run/actual-spectrum-plot.png','Actual production S4 spectrum for the Silicon example. Wavelength in nm; R/T/A plotted as percent of incident power, with raw CSV values retained as fractions.')
    EXTRA_TOPIC_IMAGES[REAL_EXAMPLE_TOPIC]=(('silicon-reference-run/actual-fields-plot.png','Actual S4 fields at 1550 nm: linear |E| / incident |E|. XY z=0.11 µm and XZ y=0; coordinates in µm.'),)
    TOPIC_IMAGES['Simulation and sample readout']=TOPIC_IMAGES[REAL_EXAMPLE_TOPIC]
    TOPIC_IMAGES['Electric fields']=EXTRA_TOPIC_IMAGES[REAL_EXAMPLE_TOPIC][0]
    TOPIC_IMAGES['Structure and layers']=('silicon-reference-run/actual-structure-native.png','Native applied Silicon example used for the actual spectrum and fields.')
    TOPIC_IMAGES['Geometry views']=TOPIC_IMAGES['Structure and layers']
    TOPIC_IMAGES['Shapes, lattice and units']=('silicon-reference-run/actual-unit-cell-native.png','Actual Silicon unit cell: centered 100 nm radius hole, 540 nm square period and applied geometry controls.')
    TOPIC_IMAGES['Field comparison and 3D playback']=('silicon-reference-run/actual-3d-fields-plot.png','Actual saved 1550 nm volume samples. Point colors are |E|²; arrows show real E at optical phase 45°. No pulse propagation or added spatial sampling.')
    TOPIC_IMAGES['Materials']=('silicon-reference-run/actual-materials-native.png','Actual example material inputs: constant Silicon n=3.48, SiO₂ n=1.45 and k=0. These are explicit approximations.')
    DOCUMENTS[REAL_EXAMPLE_TOPIC]='help_assets/silicon-reference-run/provenance.json'
    RESULT_LINKS={name:'help_assets/silicon-reference-run/'+name for name in ('results.csv','electric_fields.csv','project.json','scientific-validation.json','bundle.json','field-samples.json','basis-49/results.csv','basis-121/results.csv','actual-spectrum-native.png','actual-fields-native.png','actual-spectrum-export.png','actual-electric-field-maps.png')}

GUIDES.update({
'Choose a workspace': '''<p>At startup choose <b>Device Studio</b> or <b>Original Optical Studio</b>. These are two interfaces in the same application and use the same current project and saved library.</p><table cellspacing="8"><tr><th>Workspace</th><th>Choose it for</th></tr><tr><td>Device Studio</td><td>Editable finite devices, contacts and doping; independent Optical, Electrical and Coupled setup; linked geometry and saved results.</td></tr><tr><td>Original Optical Studio</td><td>The original layer/region tables, periodic S4 wavelength/angle scans, optical Fields, saved work, target searches and AI tools.</td></tr></table><p>Use <b>Menu → Switch workspace…</b> to change the interface later. Switching does not discard the current applied project/settings or rerun a calculation. Opening a different project and applying an edit are separate actions. An electrical/coupled setup is available in Device Studio; it is not added to the original optical controls.</p><p><a href="help-topic:Device Studio quick start">Device Studio quick start</a> · <a href="help-topic:Original Optical Studio">Original Optical Studio guide</a></p>''',
'Device Studio quick start': '''<ol><li>Choose Device Studio. Create or open a project; inspect the actual loaded structure rather than assuming the illustrative silicon device is loaded.</li><li>In Structure, set the finite device dimensions, add enabled layers and assign electrical materials. Edit thickness and donor/acceptor densities. Draw physical regions or voids, add contacts, then Apply selected object.</li><li>For a PC region, open Photonic-crystal area…; set its own size and center, unit-cell spacing and hole radius. Inspect the generated count and unused margins before applying.</li><li>In Materials, review Electrical definitions and Optical n/k separately. Assign actual optical data before an optical or coupled run.</li><li>In Simulation choose Optical, Electrical or Coupled. Complete the setup tabs, Validate setup, resolve blocking issues, then Run. Electrical-only needs a finite mesh and contacts; Optical-only does not require an electrical solve.</li><li>Open Results. Choose the saved run and inspect its measured/calculated quantities, inputs and checks. Export the full data when needed.</li></ol><p>Changes to a shared Optical or Electrical setup are also used when Coupled composes its next job. Preview geometry contains no calculated fields. Saved results use their saved snapshot, not later edits.</p><p><a href="help-topic:Optical setup tabs">Optical setup</a> · <a href="help-topic:Electrical setup tabs">Electrical setup</a> · <a href="help-topic:Coupled setup tabs">Coupled setup</a></p>''',
'Editable device structure': '''<p>Device Studio → Structure contains the device tree, linked Top XY / Cross-section XZ / 3D previews, and the selected-object inspector. Device width/depth define the full finite footprint. Layers have thickness, material, enabled state and donor/acceptor concentrations; reorder, duplicate or remove them using the structure actions.</p><p>Draw rectangles, circles, ellipses, polygons and square rings. Choose Material override or Void / subtract and the parent layer, then Apply selected object. In this finite-device inspector, <b>Full width / diameter</b> is a diameter for a circle; the original optical region table instead stores circle radius. The PC-area dialog explicitly asks for hole radius. Read the label when transferring dimensions.</p><p>Polygon vertices are x/y pairs in µm. Square rings have separate inner and outer dimensions. Later regions override earlier overlapping regions. Local doping regions override the parent layer's donor/acceptor values in their footprint. Disabled physical objects are excluded; camera, color and preview controls only affect display.</p><p>Contacts require a stable layer/surface attachment, footprint, boundary and base voltage. An ohmic boundary supplies the supported carrier reservoir; a fixed-potential electrode is a field boundary. Exposed top/bottom/side faces must be resolved by the finite mesh. An electrical contact remains ideal; optional exterior top/bottom optical material and thickness create a scattering pad in S4. A named Au contact alone is not an optical reflector. <a href="help-topic:Electrical setup tabs">Review contacts and mesh</a>.</p>''',
'PC area and automatic air holes': '''<p>The <b>Photonic-crystal area…</b> dialog defines a patterned rectangle independently of the device outline. Set area width/depth and center, cell width/depth and hole radius. The preview reports complete cells, total holes and unused edge margins. Applying creates the full set of editable holes; it does not replace the area by one representative hole.</p><p>For a <b>150 µm</b> device with a <b>100 µm</b> PC area, cells fill the 100 µm region. At 0.45 µm square spacing, 222 × 222 complete cells fit: 49,284 holes, with the remaining margin split between both sides. Arbitrary area, pitch, center and radius can be edited subject to the geometry/document limits.</p><p>Individual holes can be moved, resized, disabled or removed. Reapplying that PC area's fill replaces its generated members; inspect the count before applying. Pattern array… is the separate manual count/pitch tool. Dense previews may sample labels/drawn holes for speed; physical geometry and export retain the full document.</p><p><b>Optical selected cell</b> is a different choice. Use PC lattice size copies the spacing and an existing hole near the PC center; it does not resize the finite device or the PC region. S4 repeats the selected optical cell. Turning selection off retains the full-footprint supercell choice for custom designs without an active PC area. PC-area optical runs use one PC-pitch cell with one air hole; neither workflow provides isolated finite-device optics. Electrical fields and terminal curves keep the full footprint.</p>''',
'Device geometry and studio lighting': '''<p>Use the linked top, XZ section and 3D geometry views before a run. Selection identifies the same canonical object in the inspector; changing Section y moves the cross-section cut. Drag the 3D view to orbit and use its zoom/fit controls.</p><p>The 3D view menu provides <b>Studio lighting</b>, <b>Soft shadows</b>, <b>Surface reflections</b>, and <b>Hole and edge shading</b>. These improve the preview's surface shading, metal finish and hole walls. They are display effects, not calculated optical scattering, illumination intensity or electric fields.</p><p>Fit thin-film display proportions makes thin layers visible. Use equal physical axis scales when judging proportions; use labeled dimensions for lengths. Camera, shadows, reflections, colors and preview opacity do not change geometry, materials or solver inputs. Results field views have their own saved samples and normalization.</p>''',
'Optical setup tabs': '''<p>Device Studio → Simulation → <b>Optical</b> runs optical calculations independently of electrical charge. The seven sections are:</p><ol><li><b>Overview:</b> choose the study, review the domain and requested outputs.</li><li><b>Domain &amp; solver:</b> choose the selected periodic cell or full-footprint periodic supercell; edit cell width/depth/center and inspect excluded/clipped patterns. S4 always repeats a cell.</li><li><b>Incident light:</b> set s / p / 45° s+p polarization, incidence θ and azimuth φ. s is perpendicular to the incidence plane; p is in it.</li><li><b>Wavelength / angle sweep:</b> choose single wavelength, wavelength sweep or angle sweep. Set only the applicable ranges, positive steps and fixed wavelength; inspect the actual sample count and last grid sample.</li><li><b>Materials &amp; dispersion:</b> inspect real assignments, dataset coverage and per-material interpolation. Static electrical permittivity is not optical n/k.</li><li><b>Accuracy &amp; execution:</b> set Fourier basis, CPU/GPU backend, workers, threads, chunks, timeout and supported diagnostics. Refinement requires actual comparison runs.</li><li><b>Outputs:</b> choose Spectrum only, Spectrum then requested optical fields, or Optical fields only. Set optical field sampling and manual/extremum wavelength selection; a saved-spectrum choice must match the prepared setup. Measure phase saves specular phase during a spectrum stage.</li></ol><p>R/T/A are mandatory for a spectrum stage; a fields-only action does not create a new spectrum. Spectrum then fields saves separate stage results: a field-stage error does not erase a completed spectrum. New FDTD solver implementation is outside this update; existing optional Meep controls retain their existing runtime and geometry restrictions.</p>''',
'Electrical setup tabs': '''<p>Device Studio → Simulation → <b>Electrical</b> runs the finite-device calculation without queuing optics. The seven sections are:</p><ol><li><b>Overview:</b> choose Editable device from Structure or an explicitly fixed legacy study; inspect the actual device and study scope.</li><li><b>Study &amp; bias sweep:</b> choose the swept contact and electrostatic/I–V/C–V study; apply a start/stop/step or manual voltage list. Zero sweep offset is included as the reference. The swept contact receives base voltage + offset; other contacts keep their base voltages.</li><li><b>Contacts &amp; boundaries:</b> edit enabled contacts, base voltages and ohmic/fixed-potential boundaries; inspect the attachment and footprint before solving.</li><li><b>Materials &amp; doping:</b> assign electrical materials, edit donor/acceptor densities and local doping regions, and inspect evaluated parameters/source notes.</li><li><b>Temperature &amp; charge:</b> set the device temperature and semiconductor Fermi–Dirac Poisson or charge-free dielectric/Laplace mode. Charge-free mode ignores stored mobile carriers and dopants.</li><li><b>Finite device mesh:</b> set Nx, Ny, depth cells per enabled layer and the cell budget. Preview actual coverage of shapes and exposed contact faces; the optical cell never crops this mesh.</li><li><b>Outputs &amp; measured data:</b> enable I–V/C–V, select the initial saved-result view, and import optional measured curves with explicit units.</li></ol><p>The editable solver supports equilibrium/reverse-biased prescribed reservoirs. Forward-biased p/n reservoirs and conflicting same-carrier reservoir voltages are blocked because continuity/transport is absent. Electrical-only can run with an incomplete optical draft. Fixed legacy study choices keep their own geometry, doping, temperature and runtime limits; they do not adopt arbitrary editable geometry.</p>''',
'Coupled setup tabs': '''<p>Device Studio → Simulation → <b>Coupled</b> composes the active shared Electrical and Optical settings. The six sections are:</p><ol><li><b>Overview:</b> review both setups, the reference, resolved state/sample counts and supported outputs.</li><li><b>Electrical setup:</b> use the complete shared electrical editor. Edits also appear in standalone Electrical; the active Run action remains Coupled.</li><li><b>Optical setup:</b> use the complete shared optical editor. Edits also appear in standalone Optical; Return to transfer brings you back to mapping.</li><li><b>Transfer &amp; mapping:</b> choose zero-bias or undoped optical reference, map stable electrical layer IDs to matching optical layers, and set optical depth slices. Selected-cell carrier averages use solid-only areas and fractional mesh-cell overlap weights.</li><li><b>Response tracking:</b> choose R/T/A, Peak/Dip, reference wavelength and tracking window. Features are sampled local features; missing features stay unavailable.</li><li><b>Outputs &amp; checks:</b> review electrical volumes, spectra, index profiles, response features and optional shared I–V/C–V flags.</li></ol><p>Run order is finite Electrical → carrier/material transfer → periodic S4 spectra at the bias states → saved Results. Optical slicing does not refine the electrical mesh. Matching thickness, order, optical data and mapping are checked before launch. Mixed solid materials in one layer are blocked for coupling until material-specific averages are supported; electrical-only remains usable.</p><p>Carrier Drude corrections use editable masses and mobilities. Optional electro-optic/interband corrections are restricted to their supported GaAs conditions, not silently applied to silicon. Shared standalone optical phase/E/H requests are preserved but are not generated by the coupled backend. Select supported coupled outputs explicitly, or require all requests and resolve the blocking issue. Run standalone Optical for those outputs.</p>''',
'Electrical materials and custom definitions': '''<p>Materials → <b>Electrical</b> contains editable GaAs, ITO, AlGaAs, Silicon and Air/void definitions. Select a material to compare saved reference properties with values evaluated at temperature. Review <b>Sources</b>, assumptions and overrides; Add custom, Duplicate, Import JSON and Export JSON use stable material IDs.</p><p>Properties include static εr, band gap, electron affinity, conduction/valence density of states, conductivity/DOS effective masses, mobilities, intrinsic density, optional bulk carrier populations and explicit fixed conductivity. Concentrations use cm⁻³, mobilities cm²/(V·s), conductivity S/m, energies eV and temperature K. A conductivity override of exactly zero remains an open circuit.</p><p>GaAs/AlGaAs use Ioffe reference models; Silicon uses the Colorado parameter sheet and the recorded silicon temperature/affinity sources. AlGaAs alloy fraction is editable. Reference laws can update gap/DOS/intrinsic density while explicit edits remain overrides. Bulk mobility defaults are constants, not a fit to every doping or field.</p><p>ITO preset density, mobility, static permittivity, mass, affinity and gap are explicitly starting model assumptions; AlGaAs transport values are estimates. Replace them with sample-specific values when needed. Optical material names link to actual project n/k datasets; optional constant n/k is an explicit approximation. Static εr is never treated as optical ε. Missing optical assignment blocks Optical/Coupled without preventing an electrical-only job.</p>''',
'I–V and C–V': '''<p>In Electrical → Study &amp; bias sweep or Outputs &amp; measured data choose I–V, C–V or both. Coupled uses the same flags. Set the swept contact and base voltages first, then apply the voltage offsets.</p><p><b>I–V is a frozen-conductivity Ohmic estimate.</b> It uses zero-offset carrier populations and σ=q(nμn+pμp), unless an explicit conductivity override is supplied, including zero. It saves currents and conservation/power checks. It does not predict diode junction transport, injection, leakage, recombination or contact resistance.</p><p><b>C–V is a signed electrostatic electrode-charge derivative dQ/dV.</b> It differentiates saved displacement charge at the swept electrode with all other terminal voltages fixed. At least <b>three distinct bias states</b> are required. Endpoint derivatives are one-sided; negative signed capacitance is preserved. It does not add transported reservoir charge or AC frequency/trap dynamics.</p><p>Measured comparisons use CSV columns <b>bias_V,current_A</b> or <b>bias_V,capacitance_F</b>. They are labeled measured overlays and do not replace computed data or automatically fit the material. Refine mesh and voltage spacing before treating either estimate as quantitatively converged.</p><p>Results → I–V / C–V displays the actual saved studies. Unrequested or missing curves remain unavailable. <a href="help-topic:Results: saved runs, optical fields and phase">Saved results and exports</a>.</p>''',
'Results: saved runs, optical fields and phase': '''<p>Open Results and choose a saved run. Loading results inspects its immutable inputs and data without replacing the current editor. Restore/load setup is an explicit separate action. Available categories reflect saved files: Overview, Potential &amp; fields, Carriers &amp; charge, Energy bands, Optical response, I–V / C–V, Mesh &amp; convergence, Inputs &amp; materials, Raw data &amp; exports, Optical E/H and Specular phase.</p><p>Electrical potential/DC fields and carriers use the selected saved bias volume. Linked XY/XZ/3D probes snap to actual stored coordinates and identify the material/layer/contact where saved. Geometry view colors and display sampling do not alter complete exports. Mesh/residual/charge checks describe that run; a successful solve alone is not a mesh-convergence study.</p><p><b>Optical E/H</b> opens a genuine field-only result even without results.csv. Choose the saved wavelength/angle sample, quantity and layer; inspect XY / XZ maps, 3D E/H playback and saved samples. Ex/Ey/Ez and Hx/Hy/Hz are complex electromagnetic amplitudes with their recorded S4 normalization; they are not electrical DC fields in V/m. Playback animates steady-state harmonic phase, not pulse propagation.</p><p><b>Specular phase</b> reads actual saved reflection/transmission phase. It cannot be recovered from R/T/A power alone. Zero-signal/undefined phase remains unavailable. Spectrum then fields links the completed spectrum and its separate optical-field stage; partial or failed stages retain their actual status.</p><p>Export CSV / NPZ opens the relevant saved-data actions: complete electrical grid, original volume NPZ, optical selected-sample CSV/NPZ, full response/terminal CSVs or complete phase CSV. Export VTK applies to saved electrical volumes; figure exports use the selected actual plot. Open run folder and run/library archives retain input snapshots and provenance. On-screen row/point limits do not truncate complete exports.</p>''',
'Setup presets and validation': '''<p>Simulation → Save setup writes a named Optical, Electrical, Coupled or all-settings preset. Load preset previews changes before applying. A preset changes configuration while retaining the current finite geometry; referenced contacts and mappings must resolve to current stable IDs. A setup preset is separate from a portable project, which also includes geometry and material definitions.</p><p>Each valid edit commits through the shared project. Invalid typed values remain visible drafts with errors instead of silently becoming a numeric default. Switching modes keeps those drafts; standalone Optical checks its relevant settings, Electrical checks electrical settings, and Coupled checks both.</p><p>Validate setup resolves the real domain/materials/options and reports blocking issues with their edit sections. Fix the indicated tab, then validate again. Run uses the applied snapshot and starts without an extra simulation confirmation. A busy application blocks a second calculation; Stop requests cancellation and saved results show whether work completed, failed or was interrupted.</p><p>Validation checks representability and numerical inputs. Fourier-basis, spatial-mesh, voltage-step and wavelength convergence require actual comparison runs; a preview or Ready status does not establish them.</p>''',
'Menus, exports and retained tools': '''<p>Menu contains project actions, Switch workspace…, appearance/settings, saved work and retained optical tools. Device Studio keeps the shared finite-device builder and Optical/Electrical/Coupled setup visible. Original Optical Studio exposes the original optical controls and tools.</p><p>Additional optical tools include refractive-index/carrier sweeps, optical field maps/comparisons, target and explore-design searches, and AI training/search. Each tool has its own setup and Run action; opening a menu, selecting a result or inspecting a material does not launch a solver. Existing optional FDTD, GPU and CAD runtime setup remains in Settings; this update does not implement a new FDTD solver.</p><p>Use the active panel's export action for project JSON, device geometry, optical constants, complete result data, publication figures or run/library archives. Preview images and AI-generated design references are not simulation results. Read units and the saved model name when comparing exports from different tools.</p>''',
'Original Optical Studio': '''<p>Choose <b>Original Optical Studio</b> at startup or with <b>Menu → Switch workspace…</b> for the original optical-only layout. Its Structure layer/region tables, lattice controls, S4 wavelength/angle sweeps, optical Fields, saved work, target/explore searches and AI tools remain available. Electrical/Coupled setup is accessed through Device Studio.</p><p>For a periodic optical design, set lattice dimensions, finite layers between incident/exit half-spaces and material regions; apply the edits. Assign optical materials and inspect their coverage. Configure S4 wavelength/angle/polarization/basis, then use the fixed Run control. Fields and saved work use their original tool panels.</p><p>Original region tables use circle/ellipse radii and rectangle full widths in µm. Device Studio's finite inspector uses full width/diameter. These interfaces share the applied project and settings, so an applied edit is real in either workspace. Switching alone does not discard the project/settings or rerun jobs.</p><p>The illustrated Silicon tutorial and its verified 41-sample dataset document this original optical workflow. Its constant-index example has no automatically added electrical contacts. <a href="help-topic:Choose a workspace">Choose a workspace</a> · <a href="help-topic:Structure and layers">Original layer controls</a> · <a href="help-topic:Simulation and sample readout">Original S4 controls</a>.</p>''',
})
GUIDES['Getting started']='''<p>First choose Device Studio or Original Optical Studio at startup. The application menu can Switch workspace… later without discarding the applied project/settings or rerunning a job. Use the workspace-specific quick start below.</p><p><a href="help-topic:Choose a workspace">Choose a workspace</a> · <a href="help-topic:Device Studio quick start">Device Studio quick start</a> · <a href="help-topic:Original Optical Studio">Original Optical Studio</a></p><p>The illustrated first-structure tutorial is the original periodic Silicon-on-SiO₂ optical example, using explicit constant-index approximations. Its saved calculation is separate from your current project.</p>'''
for _title in ('Structure and layers','Shapes, lattice and units','Geometry views','Simulation and sample readout','Electric fields'):
    GUIDES[_title]='<p><b>Original Optical Studio controls.</b> For the new finite-device workflow, see <a href="help-topic:Device Studio quick start">Device Studio quick start</a>.</p>'+GUIDES[_title]
GUIDES['Materials']+='<p>Device Studio also provides the separate Electrical material catalog. See <a href="help-topic:Electrical materials and custom definitions">electrical properties and custom definitions</a>; optical n/k and electrical static permittivity are separate inputs.</p>'
GUIDES['Recent runs and saved results']+='<p>Device Studio Results also opens standalone electrical/coupled results, genuine field-only Optical E/H runs and saved Specular phase. See <a href="help-topic:Results: saved runs, optical fields and phase">current result categories and exports</a>.</p>'
GUIDES['Original Optical Studio']+='<p>The original S4/Fields workflow compiles only the applied <b>optical layer and region tables</b>, using the original lattice dimensions. An active PC area uses one fundamental PC-pitch cell with one air hole from those table patterns; designs without PC metadata retain the original lattice. Device Studio\'s canonical polygon shapes, electrical-contact optical pads and arbitrary crop settings are <b>not added automatically</b>. For an original optical mirror/contact structure, add the intended finite optical metal layers/regions explicitly. Switching retains the canonical device; choose Device Studio to simulate its supported geometry.</p>'
GUIDES['Choose a workspace']+='<p><b>Remember my choice</b> is unchecked by default. Check it to reopen the chosen interface automatically on later starts. Menu → Switch workspace… opens the choice again. Source launch supports <b>--workspace ask</b>, <b>--workspace device</b>, or <b>--workspace original</b>; these select the interface, not a new project/library.</p>'
GUIDES['Electrical setup tabs']+='''<p><b>Fine meshes and RAM planning:</b> Structure → Mesh and Electrical → Finite device mesh accept counts beyond 256 cells per axis. Enter the exact X/Y counts and depth cells per enabled layer. The finite device stays complete; only preview grid lines are thinned for display.</p><p><b>Cell budget = 0</b> selects Automatic (RAM budget), the default for new devices. A positive budget saved in an existing project is preserved. Change it to 0 or raise that explicit limit before increasing counts. Run checks the planning estimate against 60% of currently available RAM before allocating the requested mesh. A resource failure reports the requested counts and memory; it does not lower resolution.</p><p>The mesh controls show estimated peak RAM, estimated saved volume per bias, the planned linear solver and active budget. These are planning estimates, not measured memory peaks. Larger systems use a scaled iterative CG solve to avoid sparse-factorization fill-in. Fine resolution does not add transport physics or establish convergence: compare completed potential, field, I–V and C–V results at successively finer counts and voltage spacing.</p>'''
GUIDES['Electrical setup tabs']+='''<p><b>Actual voltage ranges and dense sweeps:</b> In Study &amp; bias sweep, choose Start / stop range, then By voltage step or By number of points. The point count includes both endpoints. For example, 0 to 500 V with 5,001 points gives 0.1 V spacing; 0 to 12 V with 2,401 points gives 0.005 V spacing. The step method explicitly appends the stop when a shorter final interval is needed, and the preview reports that interval.</p><p>The Range to submit readout gives the exact requested range count and distinct solved count. Zero offset is always the reference: when it is absent from the requested range, one additional solve is included. Apply range commits the complete schedule; Run also submits the current valid controls. Dense tables show the first and last 100 states and the complete count. They do not remove hidden states or change voltage spacing.</p><p>Editable device voltages no longer have the old ±100 V or 41-state UI limits. Finite high-voltage input is permitted, with available-memory checks before constructing a very large schedule. Fixed legacy ITO studies retain their supported −4 to 0 V and state limits. The selected terminal receives its base voltage plus each offset; use base 0 V and a grounded opposite terminal to reproduce a paper's terminal-voltage axis directly.</p><p>Check the paper's voltage polarity, sweep endpoints, point count or step, temperature, measurement frequency and material conditions. If a paper gives only a plotted range, a densely sampled simulation is not the original measured sampling. Record the simulation point count separately instead of inventing the paper's point count. A finer electrostatic sweep still uses the selected physics: static Poisson/Laplace and the frozen Ohmic estimate do not by themselves predict dielectric breakdown, field-dependent leakage, traps or AC capacitance.</p>'''
GUIDES['Electrical setup tabs']+='''<p><b>Dense sweep output size:</b> Finite device mesh reports the estimated total saved volume for the currently submitted sweep: estimated bytes per bias multiplied by all distinct states, including zero reference. This is an uncompressed planning estimate; actual compressed files and profiles vary. All submitted voltage states are retained. Refining voltage spacing does not refine the spatial mesh or establish spatial convergence; check voltage and mesh convergence separately.</p>'''
GUIDES['Electrical setup tabs']+='''<p><b>Physical transport &amp; breakdown settings:</b> Temperature &amp; charge → Transport &amp; breakdown → Configure physical models opens a separate parameter draft. Static electrostatics / frozen Ohmic estimate remains the default. The mode dropdown selects Semiconductor drift diffusion / continuity or Dielectric leakage with explicit material laws. Apply physical settings validates the complete configuration and atomically chooses its compatible charge equation; Cancel keeps the applied setup. Coupled uses the same applied settings.</p><p>The Semiconductor tab has optional SRH lifetimes/trap energy, high-field mobility and local impact-ionization groups. Each included group needs every required numeric value and its own source/conditions. Local impact ionization requires sourced velocity-saturation parameters. The dialog supplies model-equation references without inventing lifetimes, trap energies, barriers, ionization coefficients or parameter sources. Semiconductor transport solves continuity, so supported forward/reverse states are validated using that transport model rather than the static reservoir gate.</p><p>Materials &amp; field criteria assigns a leakage law to a named electrical material: bulk Ohmic, Poole–Frenkel, Schottky, Fowler–Nordheim or direct tunneling. Enter mechanism-specific parameters and their dataset/specimen/electrode conditions. An optional positive critical-field criterion (V/m) needs a separate source. Invalid model points are unavailable; they are not replaced with zero leakage. A field-threshold crossing is a screening criterion, not a damaged-filament or post-breakdown-current simulation.</p><p>Numerics &amp; validity shows the separate finite mesh, optional target transport depth intervals per layer and maximum internal continuation step. Continuation points help the nonlinear solver reach each requested output; they do not replace the voltage sweep or alter its point count. Use Check current device against selected model and Validate setup to see the selected solver’s actual geometry, material, doping and source constraints. The program does not silently project a patterned device or unsupported interface onto a simpler model. Refine the actual transport mesh as well as voltage samples and inspect completed continuity/Gauss checks.</p>'''
GUIDES['Electrical setup tabs']=GUIDES['Electrical setup tabs'].replace('The editable solver supports equilibrium/reverse-biased prescribed reservoirs. Forward-biased p/n reservoirs and conflicting same-carrier reservoir voltages are blocked because continuity/transport is absent.', 'The default static electrostatic model supports equilibrium/reverse-biased prescribed reservoirs. Its forward-biased p/n reservoirs and conflicting same-carrier voltages are blocked because that static model has no continuity equations. Explicit transport models use their own validated physical scope.')
GUIDES['I–V and C–V']=GUIDES['I–V and C–V'].replace('<b>I–V is a frozen-conductivity Ohmic estimate.</b>', '<b>The default I–V model is a frozen-conductivity Ohmic estimate.</b>')
GUIDES['I–V and C–V']+='''<p>To calculate current with explicit transport physics, configure and Apply a sourced model in Electrical → Temperature &amp; charge → Transport &amp; breakdown. Semiconductor drift diffusion uses contact currents from electron/hole continuity; dielectric leakage uses the selected material laws. Results retain the actual model and parameter sources. Their restrictions and unavailable points remain explicit. C–V is still the signed stationary electrode-charge derivative; selecting transport does not add a frequency-domain or dynamic-trap calculation.</p>'''
GUIDES['Electrical setup tabs']+='''<p><b>Actual 3D transport and carrier statistics:</b> Uniform planar Boltzmann devices with full-face contacts use the native depth grid; their target depth intervals are a separate numerical setting. Patterned devices, partial contacts and Fermi–Dirac transport use the actual Structure finite mesh in X, Y and depth. The dialog grays the planar depth control for the expected graph path and shows the applicable mesh; Validate setup determines the actual supported path without silently removing geometry.</p><p>Select Boltzmann or Fermi–Dirac carrier statistics explicitly in the Semiconductor tab. Boltzmann transport requires nondegenerate populations; Fermi–Dirac always uses the 3D graph. The current SRH group is a Boltzmann law and must be unchecked for Fermi–Dirac transport, since its mass-action term is incompatible with degenerate equilibrium. No substitute lifetime or recombination law is invented.</p><p>An explicit ideal quasi-Fermi interface model can be selected for a supported heterojunction, with Fermi–Dirac statistics and its own source/justification or clearly identified ideal-interface assumption. This models ideal quasi-Fermi continuity; finite thermionic transfer, interface tunneling, interface resistance and dynamic interface traps are omitted. Review actual band-alignment material inputs and independent current/Gauss checks before comparing to a paper.</p>'''
GUIDES['Electrical setup tabs']+='''<p><b>Experimental Fermi–Dirac scope:</b> This is a bulk parabolic-band graph transport model on the actual geometry, including the supplied band offsets. The explicitly selected ideal quasi-Fermi interface has zero interface resistance. Conductor interiors, including ITO, are rejected; metal electrodes may be represented by ideal boundary contacts only when that approximation is intended. Source-dependent high-field mobility and avalanche groups remain explicit. Boltzmann SRH is omitted in Fermi–Dirac mode; dynamic interface traps, finite thermionic transfer, interface tunneling and post-damage conduction remain outside this model.</p>'''
GUIDES['Drift-diffusion statistics and ideal interface']=GUIDES['Electrical setup tabs']
GUIDES['Electrical setup tabs']=GUIDES['Electrical setup tabs'].replace('set the device temperature and semiconductor Fermi–Dirac Poisson or charge-free dielectric/Laplace mode.', 'set the device temperature, semiconductor or charge-free dielectric equation, and any explicitly applied transport model/statistics.')
GUIDES['Electrical setup tabs']+='''<p><b>Voltage range &amp; model validity:</b> Editable structures accept finite voltage inputs and retain every requested sweep point, subject to available-memory planning. The Semiconductor gate readout describes the selected physical model: static prescribed reservoirs retain equilibrium/reverse compatibility restrictions, while applied semiconductor transport validates forward/reverse states through its geometry, parameter and continuity checks. Applied dielectric laws have their own sourced validity and field criteria. A large voltage input is not evidence that those physical assumptions remain valid. I–V labels refer to the selected current model; its actual method and material inputs are shown in Study &amp; bias sweep and Materials &amp; doping.</p>'''
GUIDES['Drift-diffusion statistics and ideal interface']=GUIDES['Electrical setup tabs']
GUIDES['PC area and automatic air holes']+='<p>For PC-area optical runs, Device Studio defaults to one pitch cell with one actual air hole when no optical cell is configured. Explicit full-footprint or oversized PC settings are retained, with a Domain &amp; solver validation action before Optical/Coupled launch. Original Optical Studio also uses one PC-pitch cell from its table patterns, without canonical contact pads or polygon additions. Other custom periodic designs retain their existing domain choices.</p>'
if (ASSET_ROOT/'workspace-choice-mockup.png').is_file():
    TOPIC_IMAGES['Choose a workspace']=('workspace-choice-mockup.png','AI-generated workspace-choice UI reference. This illustrates the intended interface, not a solver result or a native screenshot.')
GUIDES['Run, Stop and progress']='''<p>The fixed bottom Run starts the active calculation. Device Studio Simulation uses its selected Optical, Electrical or Coupled mode; Coupled's embedded Optical/Electrical editors keep the Run action Coupled. Original Optical Studio uses its original optical tools. Review and validate the relevant setup before running.</p><p>Another Run is blocked while the application is busy. Stop requests cancellation and waits for workers to stop; it does not mark partial work complete. Saved result status and stage errors reflect the actual work. Updates and add-on installation retain their own Cancel controls. Switching workspace does not rerun a job.</p>'''
